SELECT EXISTS(SELECT 1 FROM (SELECT f.*,f.creator_account_id AS owner FROM wallet_v1.funds f)t WHERE t.id=$2 AND t.status IN(0,1)AND LEAST(t.expires_at,t.deadline_at)>clock_timestamp() AND EXISTS(SELECT 1 FROM owned_authority_accounts a WHERE a.id=t.owner AND NOT a.disabled AND NOT EXISTS(SELECT 1 FROM owned_authority_punishments u WHERE u.account_id=a.id AND u.kind='disable_account' AND(u.starts_at IS NULL OR u.starts_at<=clock_timestamp())AND(u.expires_at IS NULL OR u.expires_at>clock_timestamp()))) AND NOT EXISTS(SELECT 1 FROM owned_social_effective_relationships b WHERE b.status=-100 AND((b.account_id=t.owner AND b.related_id=NULLIF($1::text,'')::uuid)OR(b.related_id=t.owner AND b.account_id=NULLIF($1::text,'')::uuid))) AND(t.is_open OR t.owner=NULLIF($1::text,'')::uuid OR EXISTS(SELECT 1 FROM wallet_v1.fund_participants fp WHERE fp.fund_id=t.id AND fp.account_id=NULLIF($1::text,'')::uuid AND fp.is_invited)))
